function Require([bool]$Value,[string]$Reason){if(-not $Value){throw $Reason}}
function Json([string]$Path){Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json -AsHashtable}
function ReadRepo([string]$Repo,[string[]]$Arguments){$v=@(& git.exe --no-optional-locks -C $Repo @Arguments);Require ($LASTEXITCODE -eq 0) "Git read failed: $Repo $Arguments";return ($v -join "`n").Trim()}
function StringHash([string]$Text){[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($Text)))}
$Cache=@{}
function Digest([string]$Path){$p=[IO.Path]::GetFullPath($Path);if(-not $Cache.ContainsKey($p)){$Cache[$p]=(Get-FileHash -LiteralPath $p).Hash};return $Cache[$p]}
function Fact([string]$Path){$f=Get-Item -LiteralPath $Path;return @{bytes=$f.Length;sha256=(Digest $f.FullName)}}
function Same([string]$Path,$Expected){Require ((Test-Path -LiteralPath $Path -PathType Leaf) -and (Get-Item -LiteralPath $Path).Length -eq $Expected.bytes -and (Digest $Path) -eq $Expected.sha256) "Original/predecessor file missing or changed: $Path"}
function Safe([string]$Root,[string]$Name){$r=[IO.Path]::GetFullPath($Root);$p=[IO.Path]::GetFullPath((Join-Path $r $Name));Require ($p.StartsWith($r+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)) 'Path escapes original root';return $p}
function Original([string]$Repo,[string]$Commit,[string]$Path){
    $s=[Diagnostics.ProcessStartInfo]::new('git.exe');$s.UseShellExecute=$false;$s.RedirectStandardOutput=$true;$s.RedirectStandardError=$true
    foreach($a in @('--no-optional-locks','-C',$Repo,'cat-file','blob',($Commit+':'+$Path))){[void]$s.ArgumentList.Add($a)}
    $p=[Diagnostics.Process]::Start($s);$b=[IO.MemoryStream]::new();$err=$p.StandardError.ReadToEndAsync();$p.StandardOutput.BaseStream.CopyTo($b);$p.WaitForExit();Require ($p.ExitCode -eq 0) 'Pinned authoritative source missing'
    $bytes=$b.ToArray();$value=@{text=[Text.UTF8Encoding]::new($false,$true).GetString($bytes);sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes));blob=(ReadRepo $Repo @('rev-parse',($Commit+':'+$Path)))};$b.Dispose();$p.Dispose();return $value
}
function Status([string]$Repo){$s=ReadRepo $Repo @('status','--porcelain=v1','--untracked-files=all');if($Repo -eq $Backend){$s=(($s -split "`n" | Where-Object {$_ -notlike ('*'+$Own+'*')}) -join "`n")};return $s}
