function Escape([string]$Text){$Text.Replace('|','\|').Replace("`r",'').Replace("`n",'<br>')}
function Table([string]$Title,[string[]]$Headers,$Rows,[string[]]$Fields){
    $t="# $Title`n`nTask: G-RUNTIME.03. Review-local aliases do not replace original identifiers. See the adjacent JSON for full original source locators, original artifact paths/selectors and closure/authority fields. No acceptance, severity, owner, deadline or mitigation is invented. Final runtime decision: NOT ISSUED; PENDING independent TAO/authority.`n`n"
    $t+='| '+($Headers -join ' | ')+' |'+"`n"+'| '+(@($Headers | ForEach-Object {'---'}) -join ' | ')+' |'+"`n"
    foreach($r in $Rows){$cells=@();foreach($field in $Fields){$v=$r[$field];if($v -is [array]){$v=$v -join ', '};$cells+=Escape ([string]$v)};$t+='| '+($cells -join ' | ')+' |'+"`n"};return $t
}
