function Canonical($Value){
    if($null -eq $Value){return $null}
    if($Value -is [Collections.IDictionary]){$result=[ordered]@{};foreach($key in @($Value.Keys | Sort-Object)){$result[$key]=Canonical $Value[$key]};return $result}
    if($Value -is [Collections.IEnumerable] -and $Value -isnot [string]){$items=[Collections.Generic.List[object]]::new();foreach($item in $Value){$items.Add((Canonical $item))};return ,$items.ToArray()}
    return $Value
}
